import type { CartLine } from '#shared/types/cart'
import { sumBy } from '#shared/utils/math'
import { findProduct } from '#server/utils/db'
import { computeDiscount } from '#server/utils/discount'
import { discountPercent } from '#shared/utils/discount'
import { formatMoney } from '#server/utils/money'

export interface Quote {
  subtotal: string
  discount: string
  total: string
}

export function computeQuote(lines: CartLine[], code?: string): Quote {
  const subtotal = sumBy(lines, line => (findProduct(line.slug)?.priceCents ?? 0) * line.qty)
  const discount = computeDiscount(subtotal, discountPercent(code))
  return {
    subtotal: formatMoney(subtotal),
    discount: formatMoney(discount),
    total: formatMoney(subtotal - discount),
  }
}

export interface CartLine {
  slug: string
  qty: number
}

import type { Product } from '#shared/types/product'
import { slugify } from '#shared/utils/slug'

const products: Product[] = [
  ['Notebook', 1999],
  ['Pencil', 150],
  ['Backpack', 4500],
  ['Eraser', 99],
  ['Sticky Notes', 350],
  ['Stapler', 1250],
].map(([name, priceCents]) => ({ slug: slugify(name as string), name: name as string, priceCents: priceCents as number }))

export function listProducts(): Product[] {
  return products
}

export function findProduct(slug: string): Product | undefined {
  return products.find(p => p.slug === slug)
}

export interface Product {
  slug: string
  name: string
  priceCents: number
}

/** Server-side money format for API responses: `1999` -> `19.99 USD`. */
export function formatMoney(cents: number): string {
  return `${(cents / 100).toFixed(2)} USD`
}

/** Money format for the UI: `1999` -> `$19.99`. */
export function formatMoney(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`
}

import type { Product } from '#shared/types/product'
import { useCart } from '~/composables/useCart'
import { useDiscount } from '~/composables/useDiscount'
import { useNuxtData } from '#app'
import { computed } from 'vue'
import { sumBy } from '#shared/utils/math'
import { applyDiscount } from '~/utils/discount'

/** Cart totals in cents, as shown to the customer. */
export function useCartTotal() {
  const { lines } = useCart()
  const { percent } = useDiscount()
  const { data: products } = useNuxtData<Product[]>('products')
  const subtotal = computed(() => sumBy(lines.value, (line) => {
    const product = products.value?.find(p => p.slug === line.slug)
    return (product?.priceCents ?? 0) * line.qty
  }))
  const total = computed(() => applyDiscount(subtotal.value, percent.value))
  return { subtotal, total, percent }
}

